from anomaly_detection.review_policy import sql as review_sql

def cte():
    signal_current="CASE WHEN s.source_kind='feature' THEN fj.scope_key IS NOT NULL AND NOT fj.dirty AND fj.version=s.job_version WHEN s.source_kind='actor' THEN j.session_key IS NOT NULL AND (CASE WHEN s.family='peer_service_rate_5m' AND s.primary_version IS NOT NULL THEN j.primary_version=s.primary_version ELSE NOT j.dirty AND j.version=s.job_version END) ELSE p.start_ns IS NOT NULL AND NOT p.dirty AND p.version=s.job_version END"
    signals="WITH signal_inputs AS (SELECT s.*,"+signal_current+" AS current_input,COALESCE(j.evaluation::jsonb->'pending_families' ? s.family,FALSE) AS method_pending FROM anomaly_detection.adp_case_signals s LEFT JOIN anomaly_detection.adp_jobs j ON j.session_key=s.job_session AND j.target_ns=s.target_ns LEFT JOIN anomaly_detection.adp_population_jobs p ON s.source_kind='population' AND p.start_ns=s.target_ns LEFT JOIN anomaly_detection.adp_scenario_jobs fj ON s.source_kind='feature' AND fj.scope_key=s.scope_key), "
    columns='c.case_key,c.entity_type,c.entity_key,c.issue_kind,c.service_path,c.state,c.revision,c.content_digest,c.first_ns,c.last_ns,c.updated_ns,c.body AS stored_body'
    return signals+"assessed AS (SELECT "+columns+",EXISTS(SELECT 1 FROM signal_inputs s WHERE s.case_key=c.case_key AND s.current_input) AS fresh,EXISTS(SELECT 1 FROM signal_inputs s WHERE s.case_key=c.case_key AND s.state<>'WITHDRAWN' AND (NOT s.current_input OR s.method_pending)) AS needs_recheck,(SELECT COUNT(*) FROM signal_inputs s WHERE s.case_key=c.case_key AND s.state<>'WITHDRAWN' AND NOT s.current_input) AS stale_signals,EXISTS(SELECT 1 FROM signal_inputs s WHERE s.case_key=c.case_key AND s.current_input AND ("+review_sql()+")) AS can_review,EXISTS(SELECT 1 FROM signal_inputs s WHERE s.case_key=c.case_key AND s.current_input AND NOT s.qualified AND ("+review_sql(qualified=False)+")) AS evidence_pending,(SELECT s.body::jsonb FROM signal_inputs s WHERE s.case_key=c.case_key AND s.current_input AND s.state='ACTIVE' ORDER BY s.review_eligible DESC,s.end_ns DESC,s.score DESC,s.signal_key LIMIT 1) AS current_signal,(SELECT b.label FROM anomaly_detection.adp_case_feedback b WHERE b.case_key=c.case_key AND b.case_revision=c.revision ORDER BY b.id DESC LIMIT 1) AS review_label FROM anomaly_detection.adp_cases c), effective AS (SELECT a.*,jsonb_set(stored_body::jsonb,'{strongest}',COALESCE(current_signal,stored_body::jsonb->'strongest'))::text AS body,CASE WHEN fresh AND review_label IN ('confirmed_suspicious','reviewed_benign') THEN 'REVIEWED' WHEN fresh AND review_label='needs_evidence' THEN 'EVIDENCE' WHEN can_review THEN 'READY' WHEN evidence_pending THEN 'EVIDENCE_PENDING' WHEN needs_recheck OR NOT fresh THEN 'RECHECK' WHEN state='WITHDRAWN' OR stored_body::jsonb->>'phase'='NO_CURRENT_SIGNAL' THEN 'HISTORY' ELSE 'WATCH' END AS bucket FROM assessed a) "

